import{_ as o,o as d,c as t,a2 as a}from"./chunks/framework.CAKCj7G0.js";const h=JSON.parse('{"title":"ArrayDeque","description":"","frontmatter":{},"headers":[],"relativePath":"Java/Java/集合/Collection/Queue/ArrayDeque.md","filePath":"Java/Java/集合/Collection/Queue/ArrayDeque.md","lastUpdated":1761402600000}'),c={name:"Java/Java/集合/Collection/Queue/ArrayDeque.md"};function l(i,e,r,n,p,s){return d(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="arraydeque" tabindex="-1">ArrayDeque <a class="header-anchor" href="#arraydeque" aria-label="Permalink to &quot;ArrayDeque&quot;">​</a></h1><h2 id="一、核心定义与本质" tabindex="-1">一、核心定义与本质 <a class="header-anchor" href="#一、核心定义与本质" aria-label="Permalink to &quot;一、核心定义与本质&quot;">​</a></h2><p><code>ArrayDeque</code> 是 Java 集合框架中 <strong>双端队列（Double-Ended Queue）</strong> 的实现类，底层基于 <strong>可动态扩容的数组</strong> 实现，不属于线程安全类。</p><ul><li><p>所属包：<code>java.util.ArrayDeque</code></p></li><li><p>实现接口：<code>Deque</code>、<code>Queue</code>、<code>Collection</code>，支持队列（FIFO）、栈（LIFO）两种数据结构的操作逻辑。</p></li><li><p>存储特点：数组容量默认初始化为 16，当元素满时会自动扩容（通常扩容为原容量的 2 倍）。</p></li></ul><h2 id="二、关键特性" tabindex="-1">二、关键特性 <a class="header-anchor" href="#二、关键特性" aria-label="Permalink to &quot;二、关键特性&quot;">​</a></h2><p><code>ArrayDeque</code> 的核心优势体现在“双端操作”和“效率”上，与常见集合的对比如下：</p><table tabindex="0"><thead><tr><th>特性</th><th>ArrayDeque</th><th>LinkedList</th><th>Stack（已过时）</th></tr></thead><tbody><tr><td>底层结构</td><td>动态数组</td><td>双向链表</td><td>数组（继承 Vector）</td></tr><tr><td>双端操作效率</td><td>高（O(1)，数组下标访问）</td><td>高（O(1)，链表节点操作）</td><td>不支持（仅栈顶操作）</td></tr><tr><td>随机访问效率</td><td>高（O(1)）</td><td>低（O(n)，需遍历链表）</td><td>中（O(1)，但仅支持栈操作）</td></tr><tr><td>线程安全</td><td>不安全</td><td>不安全</td><td>安全（继承 Vector，同步）</td></tr><tr><td>扩容机制</td><td>自动扩容为原容量 2 倍</td><td>无需扩容（链表动态节点）</td><td>扩容为原容量 2 倍 + 1</td></tr></tbody></table><h2 id="三、常用方法-按功能分类" tabindex="-1">三、常用方法（按功能分类） <a class="header-anchor" href="#三、常用方法-按功能分类" aria-label="Permalink to &quot;三、常用方法（按功能分类）&quot;">​</a></h2><p><code>ArrayDeque</code> 的方法围绕“双端操作”设计，可分为 <strong>队列操作</strong>、<strong>栈操作</strong>、<strong>双端通用操作</strong> 和 <strong>集合通用操作</strong> 四类。</p><h3 id="_1-队列操作-fifo-先进先出" tabindex="-1">1. 队列操作（FIFO：先进先出） <a class="header-anchor" href="#_1-队列操作-fifo-先进先出" aria-label="Permalink to &quot;1. 队列操作（FIFO：先进先出）&quot;">​</a></h3><p>模拟普通队列，仅从“队尾添加、队首移除”：</p><ul><li><p><code>boolean offer(E e)</code>：向队尾添加元素，成功返回 <code>true</code>（容量不足时抛异常，区别于 <code>Queue</code> 的 <code>offer</code>）。</p></li><li><p><code>E poll()</code>：移除并返回队首元素，队列为空时返回 <code>null</code>。</p></li><li><p><code>E peek()</code>：返回队首元素（不移除），队列为空时返回 <code>null</code>。</p></li><li><p><code>E remove()</code>：移除并返回队首元素，队列为空时抛 <code>NoSuchElementException</code>。</p></li><li><p><code>E element()</code>：返回队首元素（不移除），队列为空时抛 <code>NoSuchElementException</code>。</p></li></ul><h3 id="_2-栈操作-lifo-后进先出" tabindex="-1">2. 栈操作（LIFO：后进先出） <a class="header-anchor" href="#_2-栈操作-lifo-后进先出" aria-label="Permalink to &quot;2. 栈操作（LIFO：后进先出）&quot;">​</a></h3><p>模拟栈，仅从“队尾（栈顶）添加/移除”，推荐替代过时的 <code>Stack</code> 类：</p><ul><li><p><code>void push(E e)</code>：向栈顶（队尾）添加元素，容量不足时抛异常。</p></li><li><p><code>E pop()</code>：移除并返回栈顶（队尾）元素，栈为空时抛 <code>NoSuchElementException</code>。</p></li><li><p><code>E peek()</code>：返回栈顶（队尾）元素（不移除），栈为空时返回 <code>null</code>（与队列的 <code>peek</code> 方法复用）。</p></li></ul><h3 id="_3-双端通用操作-队首-队尾均可操作" tabindex="-1">3. 双端通用操作（队首/队尾均可操作） <a class="header-anchor" href="#_3-双端通用操作-队首-队尾均可操作" aria-label="Permalink to &quot;3. 双端通用操作（队首/队尾均可操作）&quot;">​</a></h3><p><code>Deque</code> 接口特有的方法，是 <code>ArrayDeque</code> 的核心能力：</p><ul><li><p><strong>添加元素</strong>：</p><ul><li><p><code>void addFirst(E e)</code>：向队首添加元素，容量不足时抛异常。</p></li><li><p><code>void addLast(E e)</code>：向队尾添加元素，容量不足时抛异常（等同于 <code>add(E e)</code>）。</p></li><li><p><code>boolean offerFirst(E e)</code>：向队首添加元素，成功返回 <code>true</code>。</p></li><li><p><code>boolean offerLast(E e)</code>：向队尾添加元素，成功返回 <code>true</code>（等同于队列的 <code>offer(E e)</code>）。</p></li></ul></li><li><p><strong>移除元素</strong>：</p><ul><li><p><code>E removeFirst()</code>：移除并返回队首元素，为空时抛异常（等同于队列的 <code>remove()</code>）。</p></li><li><p><code>E removeLast()</code>：移除并返回队尾元素，为空时抛异常。</p></li><li><p><code>E pollFirst()</code>：移除并返回队首元素，为空时返回 <code>null</code>（等同于队列的 <code>poll()</code>）。</p></li><li><p><code>E pollLast()</code>：移除并返回队尾元素，为空时返回 <code>null</code>。</p></li></ul></li><li><p><strong>查看元素</strong>：</p><ul><li><p><code>E getFirst()</code>：返回队首元素（不移除），为空时抛异常（等同于队列的 <code>element()</code>）。</p></li><li><p><code>E getLast()</code>：返回队尾元素（不移除），为空时抛异常。</p></li><li><p><code>E peekFirst()</code>：返回队首元素（不移除），为空时返回 <code>null</code>（等同于队列的 <code>peek()</code>）。</p></li><li><p><code>E peekLast()</code>：返回队尾元素（不移除），为空时返回 <code>null</code>。</p></li></ul></li></ul><h3 id="_4-集合通用操作" tabindex="-1">4. 集合通用操作 <a class="header-anchor" href="#_4-集合通用操作" aria-label="Permalink to &quot;4. 集合通用操作&quot;">​</a></h3><p>继承自 <code>Collection</code> 接口的基础方法：</p><ul><li><p><code>int size()</code>：返回元素个数。</p></li><li><p><code>boolean isEmpty()</code>：判断是否为空（<code>size() == 0</code>）。</p></li><li><p><code>boolean contains(Object o)</code>：判断是否包含指定元素（需重写 <code>equals()</code> 方法）。</p></li><li><p><code>void clear()</code>：清空所有元素。</p></li><li><p><code>Iterator&lt;E&gt; iterator()</code>：获取迭代器（默认从队首到队尾遍历）。</p></li><li><p><code>Object[] toArray()</code>：将元素转为数组。</p></li></ul><h2 id="四、使用场景" tabindex="-1">四、使用场景 <a class="header-anchor" href="#四、使用场景" aria-label="Permalink to &quot;四、使用场景&quot;">​</a></h2><p><code>ArrayDeque</code> 适合需要 <strong>高效双端操作</strong> 或 <strong>替代传统栈/队列</strong> 的场景，典型场景包括：</p><ol><li><p><strong>实现栈结构</strong>：用 <code>push()</code>/<code>pop()</code>/<code>peek()</code> 替代过时的 <code>Stack</code> 类，效率更高。</p></li><li><p><strong>实现队列结构</strong>：用 <code>offer()</code>/<code>poll()</code>/<code>peek()</code> 替代 <code>LinkedList</code>（数组结构随机访问更快）。</p></li><li><p><strong>需要双向遍历/操作的场景</strong>：如“最近访问记录”“滑动窗口”等，需从两端添加/删除元素。</p></li><li><p><strong>高性能场景</strong>：避免使用 <code>LinkedList</code> 的遍历开销，或 <code>Vector</code>/<code>Stack</code> 的同步开销（单线程环境）。</p></li></ol><h2 id="五、注意事项" tabindex="-1">五、注意事项 <a class="header-anchor" href="#五、注意事项" aria-label="Permalink to &quot;五、注意事项&quot;">​</a></h2><ol><li><p><strong>线程安全问题</strong>：<code>ArrayDeque</code> 非线程安全，多线程环境下需手动加锁（如用 <code>synchronized</code>），或使用并发类 <code>ConcurrentLinkedDeque</code>。</p></li><li><p><strong>null 元素禁止</strong>：<code>ArrayDeque</code> 不允许添加 <code>null</code> 元素，否则会抛 <code>NullPointerException</code>（区别于 <code>LinkedList</code>）。</p></li><li><p><strong>扩容机制</strong>：默认初始容量 16，扩容时直接翻倍，若需存储大量元素，建议初始化时指定容量（如 <code>new ArrayDeque&lt;&gt;(1000)</code>），减少扩容次数。</p></li><li><p><strong>迭代器故障快速检测</strong>：迭代过程中若通过非迭代器方法（如 <code>add()</code>/<code>remove()</code>）修改集合，会抛 <code>ConcurrentModificationException</code>。</p></li></ol><h2 id="六、代码示例-常用场景" tabindex="-1">六、代码示例（常用场景） <a class="header-anchor" href="#六、代码示例-常用场景" aria-label="Permalink to &quot;六、代码示例（常用场景）&quot;">​</a></h2><h3 id="_1-作为栈使用" tabindex="-1">1. 作为栈使用 <a class="header-anchor" href="#_1-作为栈使用" aria-label="Permalink to &quot;1. 作为栈使用&quot;">​</a></h3><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span></code></pre></div><h3 id="_2-作为队列使用" tabindex="-1">2. 作为队列使用 <a class="header-anchor" href="#_2-作为队列使用" aria-label="Permalink to &quot;2. 作为队列使用&quot;">​</a></h3><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span></code></pre></div>',31)])])}const g=o(c,[["render",l]]);export{h as __pageData,g as default};
